(function () {
  "use strict";

  /* ======================================================================
     DATA (injected via global STOCK_DATA in index.html)
     ====================================================================== */
  var data = window.STOCK_DATA;
  if (!data) {
    console.error("STOCK_DATA not found");
    return;
  }

  var sectors = Array.from(new Set(data.map(function (d) { return d.sector; })));
  var nonETF = data.filter(function (d) { return d.sector !== "ETF"; });
  var maxCap = d3.max(nonETF, function (d) { return d.marketCap; });

  /* ======================================================================
     FORMAT HELPERS
     ====================================================================== */
  function formatMarketCap(v) {
    if (v == null) return "—";
    if (v >= 1e12) return (v / 1e12).toFixed(2) + "T";
    if (v >= 1e9) return (v / 1e9).toFixed(2) + "B";
    if (v >= 1e6) return (v / 1e6).toFixed(2) + "M";
    return v.toFixed(0);
  }

  /* ======================================================================
     COLOR SCALE
     ====================================================================== */
  var colorScale = d3.scaleOrdinal()
    .domain(sectors)
    .range(d3.schemeTableau10);

  /* ======================================================================
     RADIUS SCALE
     ====================================================================== */
  var ETF_RADIUS = 14;
  var radiusScale = d3.scaleSqrt()
    .domain([0, maxCap])
    .range([8, 55]);

  function radius(d) {
    return d.sector === "ETF" ? ETF_RADIUS : radiusScale(d.marketCap || 0);
  }

  /* ======================================================================
     TOOLTIP
     ====================================================================== */
  var tooltip = d3.select("body").append("div")
    .attr("class", "tooltip")
    .style("opacity", 0);

  /* ======================================================================
     BUBBLE CHART
     ====================================================================== */
  var chartDiv = d3.select("#bubble-chart");
  var chartWidth = 700;
  var chartHeight = 620;
  var legendWidth = 150;

  var svg = chartDiv.append("svg")
    .attr("viewBox", "0 0 " + (chartWidth + legendWidth) + " " + chartHeight)
    .attr("width", chartWidth + legendWidth)
    .attr("height", chartHeight);

  var chartG = svg.append("g");

  /* ---------- sector cluster positions (grid layout, centered) ---------- */
  var cols = 3;
  var rows = Math.ceil(sectors.length / cols);
  var padX = 120;
  var padY = 80;
  var areaW = chartWidth - padX * 2;
  var areaH = chartHeight - padY * 2;
  var cellW = areaW / (cols - 1 || 1);
  var cellH = areaH / (rows - 1 || 1);

  var sectorCenter = {};
  sectors.forEach(function (s, i) {
    var col = i % cols;
    var row = Math.floor(i / cols);
    sectorCenter[s] = {
      x: padX + col * cellW,
      y: padY + row * cellH
    };
  });

  /* ---------- force simulation ---------- */
  var simulation = d3.forceSimulation(data)
    .force("x", d3.forceX(function (d) { return sectorCenter[d.sector].x; }).strength(0.35))
    .force("y", d3.forceY(function (d) { return sectorCenter[d.sector].y; }).strength(0.35))
    .force("collide", d3.forceCollide(function (d) { return radius(d) + 2; }).iterations(4))
    .force("charge", d3.forceManyBody().strength(-2))
    .alphaDecay(0.02)
    .on("tick", ticked);

  /* ---------- draw bubbles ---------- */
  var bubbles = chartG.selectAll(".bubble")
    .data(data)
    .enter().append("circle")
    .attr("class", "bubble")
    .attr("r", function (d) { return radius(d); })
    .attr("fill", function (d) { return colorScale(d.sector); })
    .attr("id", function (d) { return "bubble-" + d.ticker; });

  /* ---------- draw labels ---------- */
  var labels = chartG.selectAll(".bubble-label")
    .data(data)
    .enter().append("text")
    .attr("class", "bubble-label")
    .style("font-size", function (d) {
      var r = radius(d);
      var len = d.ticker.length;
      var sz = Math.min(r * 1.1, r * 2.2 / len) * 0.95;
      return Math.max(7, Math.min(sz, 14)) + "px";
    })
    .text(function (d) { return d.ticker; });

  function ticked() {
    bubbles
      .attr("cx", function (d) { return d.x; })
      .attr("cy", function (d) { return d.y; });
    labels
      .attr("x", function (d) { return d.x; })
      .attr("y", function (d) { return d.y; });
  }

  /* ---------- tooltip (only for non-ETF) ---------- */
  bubbles
    .on("mouseover", function (event, d) {
      if (d.sector === "ETF") return;
      tooltip.transition().duration(180).style("opacity", 0.97);
      tooltip.html(
        "<strong>" + d.ticker + "</strong><br/>" +
        "Name: " + d.name + "<br/>" +
        "Sector: " + d.sector
      )
        .style("left", (event.pageX + 14) + "px")
        .style("top", (event.pageY - 30) + "px");
    })
    .on("mousemove", function (event) {
      tooltip
        .style("left", (event.pageX + 14) + "px")
        .style("top", (event.pageY - 30) + "px");
    })
    .on("mouseout", function () {
      tooltip.transition().duration(250).style("opacity", 0);
