  var cellW = areaW / (cols - 1 || 1);
  var cellH = areaH / (rows - 1 || 1);

  var sectorCenter = {};
  sectors.forEach(function (s, i) {
    var col = i % cols;
    var row = Math.floor(i / cols);
    sectorCenter[s] = {
      x: padX + col * cellW,
      y: padY + row * cellH
    };
  });

  /* ---------- force simulation ---------- */
  var simulation = d3.forceSimulation(data)
    .force("x", d3.forceX(function (d) { return sectorCenter[d.sector].x; }).strength(0.35))
    .force("y", d3.forceY(function (d) { return sectorCenter[d.sector].y; }).strength(0.35))
    .force("collide", d3.forceCollide(function (d) { return radius(d) + 2; }).iterations(4))
    .force("charge", d3.forceManyBody().strength(-2))
    .alphaDecay(0.02)
    .on("tick", ticked);

  /* ---------- draw bubbles ---------- */
  var bubbles = chartG.selectAll(".bubble")
    .data(data)
    .enter().append("circle")
    .attr("class", "bubble")
    .attr("r", function (d) { return radius(d); })
    .attr("fill", function (d) { return colorScale(d.sector); })
    .attr("id", function (d) { return "bubble-" + d.ticker; });

  /* ---------- draw labels ---------- */
  var labels = chartG.selectAll(".bubble-label")
    .data(data)
    .enter().append("text")
    .attr("class", "bubble-label")
    .style("font-size", function (d) {
      var r = radius(d);
      var len = d.ticker.length;
      var sz = Math.min(r * 1.1, r * 2.2 / len) * 0.95;
      return Math.max(7, Math.min(sz, 14)) + "px";
    })
    .text(function (d) { return d.ticker; });

  function ticked() {
    bubbles
      .attr("cx", function (d) { return d.x; })
      .attr("cy", function (d) { return d.y; });
    labels
      .attr("x", function (d) { return d.x; })
      .attr("y", function (d) { return d.y; });
  }

  /* ---------- tooltip (only for non-ETF) ---------- */
  bubbles
    .on("mouseover", function (event, d) {
      if (d.sector === "ETF") return;
      tooltip.transition().duration(180).style("opacity", 0.97);
      tooltip.html(
        "<strong>" + d.ticker + "</strong><br/>" +
        "Name: " + d.name + "<br/>" +
        "Sector: " + d.sector
      )
        .style("left", (event.pageX + 14) + "px")
        .style("top", (event.pageY - 30) + "px");
    })
    .on("mousemove", function (event) {
      tooltip
        .style("left", (event.pageX + 14) + "px")
        .style("top", (event.pageY - 30) + "px");
    })
    .on("mouseout", function () {
      tooltip.transition().duration(250).style("opacity", 0);
    });

  /* ---------- legend ---------- */
  var legendG = svg.append("g")
    .attr("transform", "translate(" + (chartWidth + 10) + ", 30)");

  var legendItems = legendG.selectAll(".legend-group")
    .data(sectors)
    .enter().append("g")
    .attr("class", "legend-group")
    .attr("transform", function (d, i) { return "translate(0," + i * 26 + ")"; });

  legendItems.append("rect")
    .attr("width", 16).attr("height", 16)
    .attr("rx", 3)
    .attr("fill", function (d) { return colorScale(d); });

  legendItems.append("text")
    .attr("x", 22).attr("y", 13)
    .text(function (d) { return d; });

  /* ======================================================================
     DATA TABLE
     ====================================================================== */
  var tableContainer = d3.select("#stock-table");
  var table = tableContainer.append("table").attr("class", "stock-table");

  var columns = [
    { key: "ticker", label: "Ticker Symbol" },
    { key: "name", label: "Full Company Name" },
    { key: "sector", label: "Sector" },
    { key: "marketCap", label: "Market Cap", fmt: formatMarketCap }
  ];

  var thead = table.append("thead").append("tr");
  thead.selectAll("th")
    .data(columns)
    .enter().append("th")
    .text(function (c) { return c.label; });

  var tbody = table.append("tbody");
  var rows = tbody.selectAll("tr")
    .data(data)
    .enter().append("tr")
    .attr("class", "stock-row")
    .attr("id", function (d) { return "row-" + d.ticker; });

  rows.selectAll("td")
    .data(function (d) {
      return columns.map(function (c) {
        return c.fmt ? c.fmt(d[c.key]) : (d[c.key] != null ? d[c.key] : "—");
      });
    })
    .enter().append("td")
    .text(function (v) { return v; });

  /* ======================================================================
     LINKED INTERACTION: click bubble ↔ highlight table row (and vice versa)
     ====================================================================== */
  function clearSelection() {
    d3.selectAll(".stock-row").classed("highlighted", false);
    d3.selectAll(".bubble").classed("selected", false);
  }

  bubbles.on("click", function (event, d) {
    event.stopPropagation();
    clearSelection();
    d3.select(this).classed("selected", true);
    var rowEl = document.getElementById("row-" + d.ticker);
    if (rowEl) {
      d3.select(rowEl).classed("highlighted", true);
      rowEl.scrollIntoView({ behavior: "smooth", block: "nearest" });
    }
  });

  rows.on("click", function (event, d) {
    event.stopPropagation();
    clearSelection();
    d3.select(this).classed("highlighted", true);
    d3.select("#bubble-" + d.ticker).classed("selected", true);
  });

  /* click outside clears */
  d3.select("body").on("click", function () {
    clearSelection();
  });

})();
